import React from "react";
import { createRoot } from "react-dom/client";
import { BirdSongsSolution } from "./BirdSongsSolution";

const elem = document.getElementById("bird-noises-solution-root");
if (elem) {
  const root = createRoot(elem);
  root.render(<BirdSongsSolution />);
} else {
  console.error(
    "Could not mount App because #bird-noises-solution-root was nowhere to be found",
  );
}
