export const birdsHeaders = [
  "Given Order",
  "Scientific Name",
  "Common Name",
  "Wingspan",
  "Eggs",
  "Clue Answer",
];

export function SortableBirdsTable() {
  // 0: Given Order, 3: Wingspan
  const [sortBy, setSortBy] = useState<"order" | "wingspan">("order");
  const [sortAsc, setSortAsc] = useState(true);

  // Add an index to each row for "Given Order"
  const birdsWithOrder = birdsData.map((row, i) => ({
    ...row,
    givenOrder: i + 1,
  }));

  const sortedBirds = [...birdsWithOrder];
  if (sortBy === "order") {
    sortedBirds.sort((a, b) =>
      sortAsc ? a.givenOrder - b.givenOrder : b.givenOrder - a.givenOrder,
    );
  } else if (sortBy === "wingspan") {
    sortedBirds.sort((a, b) =>
      sortAsc ? a.wingspan - b.wingspan : b.wingspan - a.wingspan,
    );
  }

  function handleSort(col: "order" | "wingspan") {
    if (sortBy === col) {
      setSortAsc((asc) => !asc);
    } else {
      setSortBy(col);
      setSortAsc(true);
    }
  }

  return (
    <table className="min-w-full border border-gray-300 rounded-lg overflow-hidden my-4">
      <thead>
        <tr className="bg-gray-100">
          {birdsHeaders.map((header, idx) => {
            // Only columns 0 ("Given Order") and 3 ("Wingspan") are sortable
            const isSortable = idx === 0 || idx === 3;
            let sortCol: "order" | "wingspan" = "order";
            if (idx === 0) sortCol = "order";
            if (idx === 3) sortCol = "wingspan";
            return (
              <th
                key={header}
                className={
                  "px-4 py-2 border-b border-gray-300 text-left font-semibold" +
                  (isSortable ? " cursor-pointer select-none" : "")
                }
                onClick={
                  isSortable
                    ? () => {
                        handleSort(sortCol);
                      }
                    : undefined
                }
                aria-sort={
                  isSortable && sortBy === sortCol
                    ? sortAsc
                      ? "ascending"
                      : "descending"
                    : undefined
                }
              >
                {header}
                {isSortable && sortBy === sortCol && (
                  <span className="text-sm ml-2">{sortAsc ? "▲" : "▼"}</span>
                )}
                {isSortable && sortBy !== sortCol && (
                  <span className="text-lg ml-2 text-gray-400">↕</span>
                )}
              </th>
            );
          })}
        </tr>
      </thead>
      <tbody>
        {sortedBirds.map((row, i) => (
          <tr
            key={row.givenOrder}
            className={i % 2 === 0 ? "bg-white" : "bg-gray-50"}
          >
            <td className="px-4 py-2 border-b border-gray-200">
              {row.givenOrder}
            </td>
            <td className="px-4 py-2 border-b border-gray-200">
              {row.scientific_name}
            </td>
            <td className="px-4 py-2 border-b border-gray-200">
              {row.common_name}
            </td>
            <td className="px-4 py-2 border-b border-gray-200">
              {row.wingspan}
            </td>
            <td className="px-4 py-2 border-b border-gray-200">{row.eggs}</td>
            <td className="px-4 py-2 border-b border-gray-200">
              {row.clue_answer}
            </td>
          </tr>
        ))}
      </tbody>
    </table>
  );
}

